styl:
.white-bg.b-affsystem-text-26 {  background:#fff  }
.b-affsystem-text-26 .hello, .b-affsystem-text-26 .subtitle, .b-affsystem-text-26 .subtitle-top {  font-family:Helvetica!important;letter-spacing:0  }
.b-affsystem-text-26 .hello {  font-weight:700;font-size:22px;color:#20242f;line-height:26px  }
.b-affsystem-text-26 .text, .b-affsystem-text-26 .text-table, .b-affsystem-text-26 .text-title {  font-family:Helvetica!important;color:#20242f  }
.b-affsystem-text-26 .text, .b-affsystem-text-26 .text-table {  font-weight:400;font-size:16px;line-height:24px;letter-spacing:0  }
.b-affsystem-text-26 .text {  color:#2e3851;line-height:26px  }
.b-affsystem-text-26 .text.list {  display:list-item  }
.b-affsystem-text-26 .pb5 {  padding-bottom:5px  }
.b-affsystem-text-26 .pb15 {  padding-bottom:15px!important  }
.b-affsystem-text-26 .pb25 {  padding-bottom:25px  }
.b-affsystem-text-26 .pt15 {  padding-top:15px  }
.br-full.b-affsystem-text-26 {  border-radius:5px;-moz-border-radius:5px;-webkit-border-radius:5px  }
.b-affsystem-text-26 .text a {  font-family:Helvetica!important;text-decoration:none!important;color:#01c689!important  }
.bg-bord-full.b-affsystem-text-26 {  border:1px solid #e9ebea  }
.b-affsystem-text-26 .list-item {  background:url("https://static.cdnpub.info/files/storage/public/5e/8d/aa6a28c720a9i1g3f9/Oval Copy 3.png") left 8px no-repeat;background-size:10px;padding-left:20px  }
.b-affsystem-text-26 .ul-first {  padding-left:40px  }
@media screen and (max-width:600px) {
  .b-affsystem-text-26 .ul-first {  padding-left:8px!important  }
}
.b-affsystem-text-26 .green-number {  font-family:Helvetica!important;font-weight:700;font-size:14px;color:#fff;text-align:center;background:#01c689;border-radius:3px;padding:3px 12px;vertical-align:top;margin-right:10px  }
.b-affsystem-text-26 .bb {  border-bottom:1px solid #e9ebea  }
